import type { PdfcnTheme } from "@/registry/types/pdf-themes";

import type { PdfFormVariant } from "./form.types";

/** Style factory for fillable form layouts, derived from the active theme. */
export const createFormStyles = (
  t: PdfcnTheme,
  variant: PdfFormVariant = "underline"
) => {
  const { spacing, borderRadius, fontWeights, typography } = t.primitives;
  const borderColor = t.colors.border;
  // lighter than spacing[0.5]=2pt — more refined
  const hairline = 0.75;
  // group title rule
  const rule = 1;

  const fieldAreaByVariant: Record<PdfFormVariant, object> = {
    box: {
      borderColor,
      borderRadius: borderRadius.sm,
      borderStyle: "solid",
      borderWidth: hairline,
    },
    ghost: {
      backgroundColor: t.colors.muted,
      borderRadius: borderRadius.sm,
    },
    outlined: {
      borderColor: t.colors.foreground,
      borderRadius: borderRadius.md,
      borderStyle: "solid",
      borderWidth: hairline,
    },
    underline: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: 1,
    },
  };

  const hasPadding =
    variant === "box" || variant === "outlined" || variant === "ghost";

  return {
    column: {
      flex: 1,
    },

    columnsRow: {
      flexDirection: "row",
      gap: spacing[4],
    },
    fieldAbove: {
      marginBottom: spacing[3],
      width: "100%",
    },
    fieldArea: {
      width: "100%" as const,
      ...fieldAreaByVariant[variant],
    },

    fieldLeft: {
      alignItems: "flex-end",
      flexDirection: "row",
      gap: spacing[2],
      marginBottom: spacing[3],
    },
    fieldLeftArea: {
      flex: 1,
    },

    formDivider: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
      marginBottom: spacing[4],
    },
    formSubtitle: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.sm,
      lineHeight: t.typography.body.lineHeight,
      marginBottom: spacing[3],
    },

    formTitle: {
      color: t.colors.foreground,
      fontFamily: t.typography.heading.fontFamily,
      fontSize: typography.xl,
      fontWeight: fontWeights.bold,
      lineHeight: t.typography.heading.lineHeight,
      marginBottom: spacing[1],
    },
    group: {
      marginBottom: spacing[5],
    },

    groupTitle: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.semibold,
      letterSpacing: 0.8,
      lineHeight: 1.2,
      marginBottom: spacing[3],
      textTransform: "uppercase",
    },
    hint: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      opacity: 0.14,
      paddingBottom: hasPadding ? spacing[1] : 0,
      paddingHorizontal: hasPadding ? spacing[2] : 0,
      paddingTop: hasPadding ? spacing[1] : spacing[0.5],
    },
    labelAbove: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.medium,
      letterSpacing: 0.5,
      lineHeight: 1.2,
      marginBottom: spacing[1],
      textTransform: "uppercase",
    },

    labelLeft: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.medium,
      lineHeight: t.typography.body.lineHeight,
      paddingBottom: hasPadding ? spacing[1] : 0,
      width: 80,
    },

    root: {
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
  } as Record<string, React.CSSProperties>;
};

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/registry/bases/takumi/components/theme-provider";

import { createFormStyles } from "./form.styles";
import type {
  FormLayout,
  PdfFormField,
  PdfFormGroup,
  PdfFormProps,
} from "./form.types";

const renderFieldAbove = (
  field: PdfFormField,
  idx: number,
  styles: ReturnType<typeof createFormStyles>
) => {
  const areaHeight = field.height ?? 18;
  const areaStyle: React.CSSProperties = { ...styles.fieldArea, minHeight: areaHeight };

  return (
    <div key={`${field.label}-${idx}`} style={styles.fieldAbove}>
      <span style={styles.labelAbove}>{field.label}</span>
      <div style={areaStyle as React.CSSProperties}>
        {field.hint ? (
          <span style={styles.hint}>{field.hint}</span>
        ) : null}
      </div>
    </div>
  );
};

const renderFieldLeft = (
  field: PdfFormField,
  idx: number,
  styles: ReturnType<typeof createFormStyles>
) => {
  const areaHeight = field.height ?? 18;
  const areaStyle: React.CSSProperties = {
    ...styles.fieldArea,
    ...styles.fieldLeftArea,
    minHeight: areaHeight,
  };

  return (
    <div key={`${field.label}-${idx}`} style={styles.fieldLeft}>
      <span style={styles.labelLeft}>{field.label}</span>
      <div style={areaStyle as React.CSSProperties}>
        {field.hint ? (
          <span style={styles.hint}>{field.hint}</span>
        ) : null}
      </div>
    </div>
  );
};

const renderGroup = (
  group: PdfFormGroup,
  gi: number,
  styles: ReturnType<typeof createFormStyles>,
  labelPosition: "above" | "left"
) => {
  const layout: FormLayout = group.layout ?? "single";
  let cols: number;
  if (layout === "three-column") {
    cols = 3;
  } else if (layout === "two-column") {
    cols = 2;
  } else {
    cols = 1;
  }

  const renderField = (field: PdfFormField, idx: number) =>
    labelPosition === "left"
      ? renderFieldLeft(field, idx, styles)
      : renderFieldAbove(field, idx, styles);

  if (cols === 1) {
    return (
      <div key={`group-${gi}`} style={styles.group}>
        {group.title ? (
          <span style={styles.groupTitle}>{group.title}</span>
        ) : null}
        {group.fields.map(renderField)}
      </div>
    );
  }

  const chunkSize = Math.ceil(group.fields.length / cols);
  const chunks: PdfFormField[][] = [];
  for (let i = 0; i < group.fields.length; i += chunkSize) {
    chunks.push(group.fields.slice(i, i + chunkSize));
  }
  while (chunks.length < cols) {
    chunks.push([]);
  }

  return (
    <div key={`group-${gi}`} style={styles.group}>
      {group.title ? (
        <span style={styles.groupTitle}>{group.title}</span>
      ) : null}
      <div style={styles.columnsRow as React.CSSProperties}>
        {chunks.map((chunk, ci) => (
          <div
            key={`col-${gi}-${chunk[0]?.label ?? ci}`}
            style={styles.column}
          >
            {chunk.map(renderField)}
          </div>
        ))}
      </div>
    </div>
  );
};

export const PdfForm = ({
  title,
  subtitle,
  groups,
  variant = "underline",
  labelPosition = "above",
  noWrap = false,
  style,
}: PdfFormProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(
    () => createFormStyles(theme, variant),
    [theme, variant]
  );

  const rootStyles: React.CSSProperties[] = [styles.root];
  if (style) {
    rootStyles.push(style);
  }

  const inner = (
    <div style={Object.assign({}, ...rootStyles)}>
      {title ? <span style={styles.formTitle}>{title}</span> : null}
      {subtitle ? (
        <span style={styles.formSubtitle}>{subtitle}</span>
      ) : null}
      {title || subtitle ? <div style={styles.formDivider as React.CSSProperties} /> : null}
      {groups.map((group, gi) => renderGroup(group, gi, styles, labelPosition))}
    </div>
  );

  return noWrap ? (
    <div style={{ breakInside: "avoid" as const }}>
      {inner}
    </div>
  ) : (
    inner
  );
};

import type { CSSProperties } from "react";

/** Visual style variant for the fillable form. */
export type PdfFormVariant = "underline" | "box" | "outlined" | "ghost";

/** Column layout for a form section. */
export type FormLayout = "single" | "two-column" | "three-column";

/** Label position relative to the field. */
export type FormLabelPosition = "above" | "left";

/**
 * A single fillable field definition.
 * Props - `label` | `hint` | `height` | `width`
 * @see {@link PdfFormField}
 */
export interface PdfFormField {
  label: string;
  hint?: string;
  /**
   * Height of the blank field area in points.
   * @default 18
   */
  height?: number;
  width?: number | string;
}

/**
 * A logical group of fields with an optional section title.
 * Props - `title` | `fields` | `layout`
 * @see {@link PdfFormGroup}
 */
export interface PdfFormGroup {
  title?: string;
  fields: PdfFormField[];
  /**
   * @default 'single'
   */
  layout?: FormLayout;
}

/**
 * Fillable PDF form with grouped fields, layout variants, and label positioning options.
 * Props - `title` | `subtitle` | `groups` | `variant` | `labelPosition` | `noWrap` | `style`
 * @see {@link PdfFormProps}
 */
export interface PdfFormProps {
  title?: string;
  subtitle?: string;
  groups: PdfFormGroup[];
  /**
   * @default 'underline'
   */
  variant?: PdfFormVariant;
  /**
   * @default 'above'
   */
  labelPosition?: FormLabelPosition;
  noWrap?: boolean;
  style?: CSSProperties;
}
